import { requireAdmin } from "@/lib/auth"; import { reasonSchema } from "@/lib/admin-validations"; import { getAdminSettings, logAdminAction } from "@/lib/admin"; import { db } from "@/lib/db"; import { fail, handleApiError, ok } from "@/lib/http";
export async function POST(request: Request, { params }: { params: { id: string } }) { try { const actor = await requireAdmin(); const parsed = reasonSchema.safeParse(await request.json()); if (!parsed.success) return fail(parsed.error.issues[0]?.message || "Reason required", 422); const vendor = await db.vendor.findUnique({ where: { id: params.id } }); if (!vendor) return fail("Vendor not found", 404); const settings = await getAdminSettings(); await db.$transaction(async (tx) => { await tx.vendor.update({ where: { id: params.id }, data: { status: "REJECTED", verificationLevel: 0, isVerified: false, verificationNotes: parsed.data.reason } }); await tx.user.update({ where: { id: vendor.addedById }, data: { trustScore: { increment: settings.penaltyFakeVendor } } }); await tx.activityLog.create({ data: { userId: vendor.addedById, action: "fake_vendor_penalty", entityType: "vendor", entityId: params.id, pointsEarned: settings.penaltyFakeVendor, reason: parsed.data.reason } }); await logAdminAction(tx, { actorId: actor.id, action: "vendor_marked_fake", entityType: "vendor", entityId: params.id, reason: parsed.data.reason }); }); return ok({ removed: true }); } catch (error) { return handleApiError(error); } }
